import subprocess
result = subprocess.run(['pdftotext', '-layout', 'main.pdf', '-'], capture_output=True, text=True)
text = result.stdout
pages = text.split('\x0c')
print(f'Total pages: {len(pages)}')
for i, page in enumerate(pages[:9]):
    visuals = []
    for line in page.split('\n'):
        s = line.strip()
        if (s.startswith('Figure') or s.startswith('Table')) and ':' in s:
            visuals.append(s[:70])
    status = '✓' if visuals else '✗'
    print(f'Page {i+1} {status}: {len(visuals)} visual(s)')
    for v in visuals:
        print(f'  {v}')

# Check Conclusion/Limitations positions
for i, page in enumerate(pages):
    if 'Conclusion' in page:
        for l in page.split('\n'):
            if 'Conclusion' in l and len(l.strip()) < 30:
                print(f'\\nConclusion on page {i+1}')
                break
        break
for i, page in enumerate(pages):
    if 'Limitations' in page:
        for l in page.split('\n'):
            if 'Limitations' in l and len(l.strip()) < 30:
                print(f'Limitations on page {i+1}')
                break
        break
