    if 'Limitations' in page:
        for l in page.split('\n'):
            if 'Limitations' in l.strip() and len(l.strip()) < 40:
                print(f'Limitations starts on page {i+1}')
                break
        break
for i, page in enumerate(pages):
    if 'Conclusion' in page:
        for l in page.split('\n'):
            if 'Conclusion' in l and '5' in l[:20]:
                print(f'Conclusion on page {i+1}')
                break
        break
# Check visual per page
for i, page in enumerate(pages[:9]):
    has_fig = any(f'Figure {n}' in page for n in range(1,10))
    has_tab = any(f'Table {n}' in page for n in range(1,5))
    status = '✓' if (has_fig or has_tab) else '✗'
    print(f'Page {i+1} {status}')
